const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071,0,0,0.7071],down:[0.7071,0,0,0.7071],left:[0,0,0.7071,0.7071],right:[0,0,-0.7071,0.7071]};
const px=c=>(c-1)*1.05,pz=r=>(1-r)*1.05;
const dist=s=>(2-s.c)+(2-s.r);
function hintDir(s){return s.r<2?'up':'right';}
export function initialState(){return {c:0,r:0,moves:0,msg:'Reach the gold goal square.',hint:false,won:false};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action,s={...state};
if(s.won){s.msg='You already reached the goal in '+s.moves+' moves. Press Reset to play again.';return s;}
if(a==='hint'){s.hint=true;s.msg='Hint: move '+hintDir(s)+' to get one step closer.';return s;}
const d=D[a];if(!d)return state;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2){s.msg='Cannot move '+a+': that would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=false;
if(c===2&&r===2){s.won=true;s.msg='You reached the goal in '+s.moves+' moves! The shortest route is 4 moves.'+(s.moves===4?' Perfect!':'');}
else s.msg='Moved '+a+'. '+dist(s)+' steps to go.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const h=hintDir(s);
return {nodes:{token:{position:[px(s.c),0.4,pz(s.r)]},hintArrow:{visible:s.hint&&!s.won,position:[px(s.c),0.2,pz(s.r)],quaternion:Q[h]}},
readouts:{moves:s.moves,steps:dist(s)},
goal:{status:s.won?'won':'playing',message:s.msg}};}
